const config = $input.first().json;
const { date, timezone, working_days } = config;

// Validate YYYY-MM-DD format
const regex = /^\d{4}-\d{2}-\d{2}$/;

if (typeof date !== 'string' || !regex.test(date)) {
  return [{
    json: {
      valid: false,
      error: 'Invalid date format. Use YYYY-MM-DD.'
    }
  }];
}

// Validate actual calendar date
const [year, month, day] = date.split('-').map(Number);

const parsedDate = new Date(Date.UTC(year, month - 1, day));

if (
  parsedDate.getUTCFullYear() !== year ||
  parsedDate.getUTCMonth() !== month - 1 ||
  parsedDate.getUTCDate() !== day
) {
  return [{
    json: {
      valid: false,
      error: 'Invalid calendar date.'
    }
  }];
}

// Get today's date using configured timezone
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

// Reject past dates
if (date < today) {
  return [{
    json: {
      valid: false,
      error: 'Appointment date must be today or in the future.'
    }
  }];
}

// Convert JavaScript weekday (Sunday = 0)
// to ISO weekday (Monday = 1, Sunday = 7)
const dayOfWeek = parsedDate.getUTCDay() || 7;

// Check configured working days
if (!working_days.includes(dayOfWeek)) {
  const dayName = new Intl.DateTimeFormat('en-US', {
    weekday: 'long',
    timeZone: 'UTC'
  }).format(parsedDate);

  return [{
    json: {
      valid: false,
      error: `Appointments are not available on ${dayName}s.`
    }
  }];
}

return [{
  json: {
    ...config,
    valid: true,
    day_of_week: dayOfWeek,
    working_hours: {
      start: `${String(config.openingHour).padStart(2, '0')}:00`,
      end: `${String(config.closingHour).padStart(2, '0')}:00`
    }
  }
}];

const config = $('Configuration').first().json;
const appointmentType = config.appointment_type;

const selectedType = config.types.find(
  type => type.name === appointmentType
);

if (!selectedType) {
  return [{
    json: {
      valid: false,
      error: 'Invalid appointment type.',
      allowed_types: config.types.map(type => type.name)
    }
  }];
}

return [{
  json: {
    valid: true,
    appointment_type: selectedType.name,
    duration_minutes: Number(selectedType.duration_minutes)
  }
}];

const config = $('Configuration').first().json;

const date = config.date;
const timezone = config.timezone;
const appointmentType = config.appointment_type;

const selectedType = config.types.find(
  type => type.name === appointmentType
);

if (!selectedType) {
  throw new Error(`Unknown appointment type: ${appointmentType}`);
}

const duration = Number(selectedType.duration_minutes);
const interval = Number(config.slot_interval_minutes);

const openingMinutes = Number(config.openingHour) * 60;
const closingMinutes = Number(config.closingHour) * 60;
const lunchStart = Number(config.lunch_start) * 60;
const lunchEnd = Number(config.lunch_end) * 60;

if (
  !Number.isFinite(duration) || duration <= 0 ||
  !Number.isFinite(interval) || interval <= 0
) {
  throw new Error('Invalid appointment duration or slot interval.');
}

// Convert a local date and time in the configured timezone to a Date.
function localToUtc(dateString, minutes) {
  const [year, month, day] = dateString.split('-').map(Number);

  const hour = Math.floor(minutes / 60);
  const minute = minutes % 60;

  const target = Date.UTC(year, month - 1, day, hour, minute);
  let guess = target;

  for (let i = 0; i < 3; i++) {
    const parts = new Intl.DateTimeFormat('en-GB', {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23'
    }).formatToParts(new Date(guess));

    const values = Object.fromEntries(
      parts.map(part => [part.type, part.value])
    );

    const representedAsUtc = Date.UTC(
      Number(values.year),
      Number(values.month) - 1,
      Number(values.day),
      Number(values.hour),
      Number(values.minute),
      Number(values.second)
    );

    guess += target - representedAsUtc;
  }

  return new Date(guess);
}

// Get the requested day's boundaries.
const [year, month, day] = date.split('-').map(Number);

const nextDate = new Date(Date.UTC(year, month - 1, day + 1))
  .toISOString()
  .slice(0, 10);

const dayStart = localToUtc(date, 0);
const dayEnd = localToUtc(nextDate, 0);

// Get current time in the configured timezone.
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

const now = Date.now();

// Read calendar events.
const events = $input.all()
  .map(item => item.json)
  .filter(event => event.status !== 'cancelled')
  .map(event => {
    const start = event.start;
    const end = event.end;

    if (!start || !end) return null;

    // All-day events: end date is exclusive.
    if (start.date && end.date) {
      return {
        start: localToUtc(start.date, 0),
        end: localToUtc(end.date, 0)
      };
    }

    // Timed events.
    if (start.dateTime && end.dateTime) {
      return {
        start: new Date(start.dateTime),
        end: new Date(end.dateTime)
      };
    }

    return null;
  })
  .filter(event =>
    event &&
    !isNaN(event.start.getTime()) &&
    !isNaN(event.end.getTime()) &&
    event.start < dayEnd &&
    event.end > dayStart
  );

// Format times using the configured timezone.
function formatTime(timestamp) {
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: timezone,
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  }).format(timestamp);
}

// Generate valid appointment slots.
const availableStarts = [];

for (
  let minute = openingMinutes;
  minute + duration <= closingMinutes;
  minute += interval
) {
  const endMinute = minute + duration;

  // Exclude appointments overlapping lunch.
  const overlapsLunch =
    minute < lunchEnd &&
    endMinute > lunchStart;

  if (overlapsLunch) continue;

  const startTime = localToUtc(date, minute);
  const endTime = new Date(
    startTime.getTime() + duration * 60 * 1000
  );

  // Exclude past slots when checking today.
  if (date === today && startTime.getTime() < now) {
    continue;
  }

  // Exclude slots overlapping calendar events.
  const isBooked = events.some(event =>
    startTime < event.end &&
    endTime > event.start
  );

  if (isBooked) continue;

  availableStarts.push({
    minute,
    start: startTime,
    end: endTime
  });
}

// Combine consecutive available slots into ranges.
const availableRanges = [];
let currentRange = null;

for (const slot of availableStarts) {
  if (
    currentRange &&
    slot.minute === currentRange.lastMinute + interval
  ) {
    currentRange.end_time = formatTime(slot.end);
    currentRange.lastMinute = slot.minute;
  } else {
    if (currentRange) {
      delete currentRange.lastMinute;
      availableRanges.push(currentRange);
    }

    currentRange = {
      start_time: formatTime(slot.start),
      end_time: formatTime(slot.end),
      lastMinute: slot.minute
    };
  }
}

if (currentRange) {
  delete currentRange.lastMinute;
  availableRanges.push(currentRange);
}

return [{
  json: {
    date,
    appointment_type: appointmentType,
    duration_minutes: duration,
    available_ranges: availableRanges,
    total_ranges: availableRanges.length
  }
}];
